import React, { useState, useEffect } from "react";
import axios from "axios";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";

function Register() {
  const location = useLocation();
  // Ensure we safely get eventId from state
  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "General Admission";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
    photo: "" 
  });

  const [registering, setRegistering] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setRegistering(true);

    try {
      // Ensure the URL matches your server.js port (5000)
      const res = await axios.post("http://localhost:5000/register", formData);

      if (res.data.success) {
        alert("Registration Successful! User ID: " + res.data.userId);
        // Add navigation or state update here to move to QR section
      } else {
        alert("Error: " + res.data.message);
      }
    } catch (error) {
      console.error("Submission Error:", error);
      alert("Registration failed. Please ensure the backend is running on port 5000.");
    } finally {
      setRegistering(false);
    }
  };

  return (
    <div style={{ padding: "20px", textAlign: "center" }}>
      <Navbar />
      <h2>Event Registration</h2>
      {/* Used eventName here to fix the eslint warning */}
      <h3>Registering for: {eventName}</h3>

      <form onSubmit={handleSubmit} style={{ maxWidth: "400px", margin: "auto" }}>
        <input name="name" placeholder="Enter Name" onChange={handleChange} required style={inputStyle} />
        <input name="college_name" placeholder="College Name" onChange={handleChange} required style={inputStyle} />
        <input name="phone" placeholder="Phone Number" onChange={handleChange} required style={inputStyle} />
        <input name="email" placeholder="Email" onChange={handleChange} required style={inputStyle} />
        
        <button type="submit" disabled={registering} style={btnStyle}>
          {registering ? "Registering..." : "Register"}
        </button>
      </form>
    </div>
  );
}

const inputStyle = { display: "block", width: "100%", padding: "10px", margin: "10px 0" };
const btnStyle = { padding: "10px 20px", backgroundColor: "#007bff", color: "white", border: "none", cursor: "pointer" };

export default Register;
